DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='social_reserve_publish'; d:=replace(d,'platform=_platform AND is_test=p.is_test AND created_at','platform=_platform AND is_test=p.is_test AND (NOT p.is_test OR post_id IN (SELECT id FROM social_launch_posts WHERE theme=p.theme)) AND created_at'); d:=replace(d,'platform=_platform AND is_test=p.is_test AND scheduled_for','platform=_platform AND is_test=p.is_test AND (NOT p.is_test OR post_id IN (SELECT id FROM social_launch_posts WHERE theme=p.theme)) AND scheduled_for'); d:=replace(d,'o.is_test=p.is_test AND o.archived_at','o.is_test=p.is_test AND (NOT p.is_test OR o.theme=p.theme) AND o.archived_at'); EXECUTE d; END $$;